export function t(locale, key, variables = {}) {
  const template = MESSAGES[locale]?.[key] ?? EN[key] ?? key;
  return String(template).replace(/\{(\w+)\}/g, (_, name) => variables[name] ?? `{${name}}`);
}

export function translateDocument(locale, root = document) {
  root.querySelectorAll('[data-i18n]').forEach((element) => {
    element.textContent = t(locale, element.dataset.i18n);
  });
  root.querySelectorAll('[data-i18n-aria-label]').forEach((element) => {
    element.setAttribute('aria-label', t(locale, element.dataset.i18nAriaLabel));
  });
  root.querySelectorAll('[data-i18n-placeholder]').forEach((element) => {
    element.setAttribute('placeholder', t(locale, element.dataset.i18nPlaceholder));
  });
  const title = root.querySelector('title');
  if (title) title.textContent = t(locale, 'meta.title');
}
